R=Path(__file__).resolve().parents[1];O=R/'results/training_round3/fields';a=np.load(O/'confirm.npz');b=np.load(R/'results/training_round2/deep_teacher/confirm.npz');assert np.array_equal(a['rows'],b['rows']);y=a['y'];pl=json.loads((R/'results/training_round2/deep_teacher/selection_lock.json').read_text());fl=json.loads((O/'selection_lock.json').read_text());p=a['p'];q=b['p'];old=(q>=pl['threshold'])==y;new=(p>=fl['threshold'])==y;g=int((new&~old).sum());l=int((old&~new).sum());r={'field_accuracy':float(new.mean()),'parent_accuracy':float(old.mean()),'gains':g,'losses':l,'net':g-l,'paired_p_unadjusted':float(binomtest(g,g+l,.5).pvalue) if g+l else 1,'scope':'Exploratory paired diagnostic on reused14k. The .85parent/.15fields blend was preregistered while fields confirmation was fitting; no weight search.'};pb=.85*q+.15*p;r['predeclared_parent_blend']={'accuracy':float(accuracy_score(y,pb>=pl['threshold'])),'logloss':float(log_loss(y,pb))};(O/'paired_parent_diagnostic.json').write_text(json.dumps(r,indent=2));m=CatBoostClassifier();m.load_model(str(O/'confirmation_model.cbm'));pd.DataFrame({'feature':m.feature_names_,'importance':m.get_feature_importance()}).sort_values('importance',ascending=False).to_csv(O/'confirmation_feature_importances.csv',index=False);print(json.dumps(r,indent=2))
